import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.DekDpfFM.js";const k=JSON.parse('{"title":"What loom is","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-loom.md","filePath":"guide/what-is-loom.md","lastUpdated":1794312142000}'),i={name:"guide/what-is-loom.md"};function r(n,e,h,d,l,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="what-loom-is" tabindex="-1">What loom is <a class="header-anchor" href="#what-loom-is" aria-label="Permalink to &quot;What loom is&quot;">​</a></h1><blockquote><p><strong>Write a kernel once, in C++ or CUDA, and call it as a function of your framework — Jax, Torch, NumPy or CuPy — with the gradient you wrote for it.</strong></p></blockquote><p>You have an operation that a few <code>jnp</code> or <code>torch</code> calls do not express well. Perhaps it is a loop over a structure whose size depends on the data, perhaps it is C++ you already own, perhaps it is simply faster and clearer as a loop. You want it to sit in your model like any other operation: accept arrays, work under <code>jit</code> and <code>vmap</code>, and be differentiable.</p><p>loom is what turns the C++ function into that.</p><h2 id="the-shape-of-it" tabindex="-1">The shape of it <a class="header-anchor" href="#the-shape-of-it" aria-label="Permalink to &quot;The shape of it&quot;">​</a></h2><p>You provide two things.</p><p><strong>The kernel.</strong> A functor in plain C++ (or CUDA), working on views of tensors:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HD </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> operator</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">()</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> coords</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">args</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> batch_axes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    args.outputs.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">next</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( coords ) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> args.inputs.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( coords ) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> args.inputs.coef </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> laplacian</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( coords, args );</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>The call.</strong> One Python function, which names the kernel, passes the arguments, and says what is written:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> loom.ffi_call( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;step&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, _forward, _backward,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> loom.mutable( u ),</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    coef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> coef )</span></span></code></pre></div><p>loom provides everything between the two: it generates the glue, compiles it, caches it, registers it with the framework, binds the framework&#39;s buffers to the views the kernel reads, allocates the outputs, and plugs the adjoint into the framework&#39;s own autodiff.</p><h2 id="two-worlds" tabindex="-1">Two worlds <a class="header-anchor" href="#two-worlds" aria-label="Permalink to &quot;Two worlds&quot;">​</a></h2><p>Your users each work in one framework, and expect its arrays back. Your code, if it had to care which one, would be written four times, or full of <code>if</code>s. loom separates the two:</p><ul><li><strong>inside</strong>, every value is a loom tensor, whichever framework owns its buffer. It carries what its dimensions mean and how many items they really hold, and it has the same operations everywhere. The code around your kernels is written once, and reads the same under NumPy, CuPy, Torch and Jax;</li><li><strong>at the boundary</strong>, values are converted: the user&#39;s arrays come in as they are, and what goes back out is an array of <em>their</em> framework. One line at the end of a module sets it:</li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">loom.export_namespace( </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">globals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() )</span></span></code></pre></div><p>A user never writes <code>.value</code> to get their array back, and never wraps anything to get in.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>One kernel, four frameworks</strong></td><td>The same C++ is called from Jax (inside <code>jit</code>, <code>vmap</code>, <code>grad</code>), from Torch (<code>torch.autograd.Function</code>, <code>torch.func.vmap</code>, <code>torch.compile</code>), and from NumPy and CuPy (forward only). → <a href="./frameworks">Frameworks</a></td></tr><tr><td><strong>One kind of data inside</strong></td><td>Whatever the framework, your code sees loom tensors, and your users get their own arrays back. → <a href="./tensors">Tensors</a></td></tr><tr><td><strong>Dimension-agnostic bodies</strong></td><td>Coordinates are read by name. <code>coords + axis</code> is the neighbour along that axis. The same kernel serves 2-D and 3-D, batched or not. → <a href="./axes">Axes</a></td></tr><tr><td><strong>Roles on the values</strong></td><td><code>loom.out</code>, <code>loom.mutable</code>, <code>loom.scratch</code>, <code>loom.unbound</code> say what each argument is, where it is passed. → <a href="./arguments">Roles</a></td></tr><tr><td><strong>Hand-written adjoints</strong></td><td>The backward is a kernel, wired into the framework&#39;s autodiff and checked by <code>loom.testing.check_grad</code>. → <a href="./adjoint">The adjoint</a></td></tr><tr><td><strong>Run-time sizes</strong></td><td>A kernel counts, the host reads the total, the next buffer is exactly that big, also under <code>jit</code>. → <a href="./dynamic-sizes">Sizes known at run time</a></td></tr><tr><td><strong>Structured tensors</strong></td><td>Named axes, computed extents, aggregates of tensors, <code>CsrTensor</code> for ragged data. → <a href="./tensors">Tensors</a></td></tr><tr><td><strong>Compilation handled</strong></td><td>Compiled on first call and cached; or precompiled into a catalogue for a wheel. → <a href="./compilation">Compilation</a></td></tr><tr><td><strong>Several devices, several processes</strong></td><td>The same program runs over boxes of data spread across cards or MPI ranks. → <a href="./distributed">Distributed programs</a></td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>When Python reaches <code>loom.ffi_call</code>:</p><ol><li>loom reads what it was given: shapes, element types, device, which framework owns the arrays.</li><li>It renders a C++ source: a body that calls your <code>kernel( queue, batch_axes, args )</code>, and a small entry per framework that decodes what that framework hands over (the XLA frame for Jax, plain pointers for Torch, NumPy and CuPy). The <code>args</code> carry your arguments under their Python names, in groups: <code>args.inputs</code>, <code>args.outputs</code>, <code>args.scratch</code>, and for the adjoint <code>args.grad_of_outputs</code> and <code>args.grad_of_inputs</code>.</li><li>It compiles that source with the device&#39;s compiler and caches the library, keyed by a hash of the source and everything it was rendered with. A second call, or a second process, finds it.</li><li>It registers the entry with the framework (an XLA FFI target for Jax, eagerly and under <code>jit</code>) or calls it directly with the buffers&#39; addresses (Torch, NumPy, CuPy).</li><li>If there is an adjoint, it is registered as the backward of the call: <code>jax.custom_vjp</code> for Jax, <code>torch.autograd.Function</code> for Torch.</li><li>It hands back what the call wrote, in the world of the caller.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   Python                          loom                                   C++</span></span>
<span class="line"><span> ┌──────────┐   ffi_call   ┌───────────────────────────┐   kernel( queue, batch_axes, args )</span></span>
<span class="line"><span> │ jax array│ ───────────► │ read shapes / dtypes      │ ──────────────────────────────────►</span></span>
<span class="line"><span> │ torch    │              │ render + compile + cache  │    your functor, on views of</span></span>
<span class="line"><span> │ numpy    │ ◄─────────── │ bind buffers, allocate    │ ◄──────────────────────────────────</span></span>
<span class="line"><span> │ cupy     │   outputs    │ register forward + adjoint│</span></span>
<span class="line"><span> └──────────┘              │                           │</span></span>
<span class="line"><span>                           └───────────────────────────┘</span></span></code></pre></div><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What it is not&quot;">​</a></h2><p><strong>It is not a deep-learning framework.</strong> loom tensors have the operations that the code around a kernel needs, so that this code stays generic; the model itself, its layers and its optimiser, stay in Jax or Torch. loom provides the bridge for the operation you write yourself.</p><p><strong>It does not auto-differentiate your C++.</strong> The adjoint is a kernel you write, with the same tools. loom makes it easy to wire and to check, not to avoid.</p><p><strong>It does not replace <code>jnp</code> or <code>torch</code> where they suffice.</strong> A kernel is worth its cost when the loop is the natural way to say the operation, or when the C++ already exists.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./why-not-trivial">Why it is not trivial</a> · <a href="./installing">Installing</a> · or go straight to <a href="/loom/tutorials/diffusion">Diffusion</a>.</p>`,28)])])}const u=a(i,[["render",r]]);export{k as __pageData,u as default};
